const $=s=>document.querySelector(s);
const modules=[['Overview','▦'],['Approvals','☑'],['Finance','◴'],['Operations','▧'],['Customers','♙'],['People','♧'],['Automations','ϟ'],['Reports','▥']];
const businesses=[{id:'retail',name:'Vishwa Retail',type:'Retail · 4 branches',symbol:'▤',sales:842500,cash:3210000,margin:'28.4%',target:84,health:'On track'},{id:'trading',name:'Vishwa Trading',type:'Trading · 2 branches',symbol:'◇',sales:326800,cash:1860000,margin:'22.1%',target:72,health:'On track'},{id:'factory',name:'Vishwa Manufacturing',type:'Manufacturing · 1 facility',symbol:'▥',sales:115200,cash:770000,margin:'18.6%',target:56,health:'Needs attention'}];
let page='Overview',decisions=[{id:1,title:'Restock your best-selling essentials',desc:'Vishwa Retail · 8 SKUs below reorder point',amount:148500,type:'Purchase order',icon:'▧',why:'Eight fast-moving products have less than 3 days of stock. This draft restores 14 days of cover using the usual supplier.',detail:'PO-2026-0842 · Lanka Wholesale',priority:'Stockout risk'},{id:2,title:'Follow up on an overdue invoice',desc:'Vishwa Trading · Sunrise Distributors',amount:285000,type:'Collection reminder',icon:'◷',why:'Invoice INV-1048 is 14 days overdue. A payment reminder has been drafted for your review.',detail:'INV-1048 · Due September 28',priority:'14 days overdue'},{id:3,title:'Review tomorrow’s shift coverage',desc:'Vishwa Retail · Colombo branch',amount:null,type:'Shift adjustment',icon:'♧',why:'Two leave requests overlap tomorrow’s afternoon shift. A revised roster assigns available team members.',detail:'Colombo · October 13, 14:00–22:00',priority:'2 leave requests'}],activity=[];
const money=n=>n.toLocaleString('en-US');const scope=()=>businesses.filter(b=>$('#business').value==='all'||b.id===$('#business').value);const factor=()=>({today:1,week:5.8,month:19.4}[$('#period').value]);
$('#nav').innerHTML=modules.map(([name,icon])=>`<button data-page="${name}"><span class="nav-icon">${icon}</span><span class="nav-text">${name}</span>${name==='Approvals'?'<span class="count">3</span>':''}</button>`).join('');
function stats(){let list=scope(),sales=Math.round(list.reduce((a,b)=>a+b.sales,0)*factor()),cash=list.reduce((a,b)=>a+b.cash,0);let data=page==='Operations'?[['Stock value','8,420,000','↑ 4.2%','across selected warehouses','▧'],['Orders to fulfill','48','12 ready','36 being prepared','▤'],['Low-stock items','8','3 urgent','require a reorder','!'],['Fulfillment rate','96.8%','↑ 2.1%','vs. previous period','↗']]:page==='Finance'?[['Cash position',money(cash),'↑ 8.2%','vs. previous period','◴'],['Receivables','1,240,000','14 overdue','across 32 invoices','↗'],['Payables','860,000','5 due soon','next 7 days','↙'],['Net cash flow','+380,000','↑ 12.4%','vs. previous period','≈']]:[['Sales '+($('#period').value==='today'?'today':$('#period').value==='week'?'this week':'this month'),money(sales),'↑ 12.8%','vs. previous period','↗'],['Cash position',money(cash),'↑ 8.2%','vs. previous period','◴'],['Gross margin','25.6%','↑ 2.4 pts','vs. previous period','◈'],['Pending decisions',String(decisions.length),decisions.length+' to review','your attention makes a difference','☑']];return `<div class="stats">${data.map(([label,num,change,foot,icon],i)=>`<button class="stat" data-stat="${label}"><div class="stat-label">${label}<span class="stat-icon">${icon}</span></div><h2>${num.includes(',')?'<small>LKR</small>':''}${num}</h2><div class="stat-foot"><span class="${i===3||change.includes('overdue')?'down':'up'}">${change}</span>${foot}</div></button>`).join('')}</div>`}
function chart(){let total=scope().reduce((a,b)=>a+b.sales,0)*factor();return `<section class="card"><div class="card-head"><div><h3>${page==='Finance'?'Cash flow':page==='Operations'?'Order fulfillment':'Revenue overview'}</h3><p class="card-sub">${$('#business').selectedOptions[0].text} · ${$('#period').selectedOptions[0].text}</p></div><span class="live"><i></i>Sample snapshot</span></div><div class="chart-top"><div class="chart-total">${page==='Operations'?'48 orders':'LKR '+money(Math.round(total))}<span>↗ 12.8%</span></div><div class="legend"><span><i></i>Current period</span><span><i class="past"></i>Previous</span></div></div><div class="chart"><svg viewBox="0 0 620 210" role="img" aria-label="Illustrative current and previous period trend"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#66a27e" stop-opacity=".15"/><stop offset="1" stop-color="#66a27e" stop-opacity="0"/></linearGradient></defs>${[30,70,110,150].map((y,i)=>`<line x1="45" y1="${y}" x2="605" y2="${y}" stroke="#eef1f2" stroke-dasharray="3 4"/><text x="3" y="${y+3}">${[400,300,200,100][i]}k</text>`).join('')}<path d="M45 149 C85 149 82 126 115 132 S167 148 195 125 S242 139 269 108 S316 103 344 113 S390 119 418 84 S465 88 491 62 S550 76 605 40" fill="none" stroke="#c9d0d2" stroke-width="2" stroke-dasharray="5 5"/><path d="M45 154 C80 149 93 151 115 140 S154 145 182 117 S224 103 247 115 S289 144 317 109 S356 85 380 94 S425 79 450 67 S494 67 520 47 S562 57 605 22 L605 178 L45 178 Z" fill="url(#fill)"/><path d="M45 154 C80 149 93 151 115 140 S154 145 182 117 S224 103 247 115 S289 144 317 109 S356 85 380 94 S425 79 450 67 S494 67 520 47 S562 57 605 22" fill="none" stroke="#589475" stroke-width="2.5"/><circle cx="605" cy="22" r="4" fill="#589475" stroke="white" stroke-width="3"/>${['08:00','10:00','12:00','14:00','16:00','18:00','20:00'].map((t,i)=>`<text x="${45+i*89}" y="201">${$('#period').value==='today'?t:$('#period').value==='week'?['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]:[1,5,10,15,20,25,30][i]}</text>`).join('')}</svg></div><div class="chart-bottom"><span>Peak performance <b> ${page==='Operations'?'Colombo fulfillment':'Vishwa Retail'}</b></span><span>View breakdown ↗</span></div></section>`}
function decisionCard(full=false){return `<section class="card"><div class="card-head"><div><h3>Needs your attention <span class="badge">${decisions.length}</span></h3><p class="card-sub">Prioritized by impact. Ready for your decision.</p></div><span style="color:#a9b1b9">···</span></div><div class="decision-list">${decisions.length?decisions.map(d=>`<article class="decision" tabindex="0" role="button" data-decision="${d.id}" aria-label="Review ${d.title}"><span class="decision-icon">${d.icon}</span><div><h4>${d.title}</h4><p>${d.desc}</p></div><div class="amount">${d.amount?'LKR '+money(d.amount):'Tomorrow'}<span class="pill">${d.priority}</span></div></article>`).join(''):'<div class="empty">✓ You’re all caught up.<br><small>Every decision has been reviewed.</small></div>'}</div><div class="decision-action"><span>Human approval, always.</span><button data-review>Review ${decisions.length} decisions →</button></div></section>`}
function businessTable(){return `<section class="card"><div class="card-head"><div><h3>Your businesses</h3><p class="card-sub">One group. A complete picture.</p></div><button id="all-businesses">View all ↗</button></div><div class="table-wrap"><table><thead><tr><th>BUSINESS</th><th>SALES</th><th>MARGIN</th><th>TARGET</th><th>STATUS</th></tr></thead><tbody>${scope().map(b=>`<tr data-business="${b.id}" tabindex="0"><td><div class="business-cell"><span class="business-symbol">${b.symbol}</span><div><strong>${b.name}</strong><small>${b.type}</small></div></div></td><td>${money(Math.round(b.sales*factor()))}</td><td>${b.margin}</td><td><span class="bar"><i style="width:${b.target}%"></i></span>${b.target}%</td><td><span class="health ${b.id==='factory'?'warn':''}">${b.health}</span></td></tr>`).join('')}</tbody></table></div></section>`}
function events(){return `<section class="card"><div class="card-head"><div><h3>Across your workspace</h3><p class="card-sub">The small moments moving business forward.</p></div><span class="live"><i></i>Activity</span></div><div class="activity">${[...activity,['Payment received · LKR 125,000','Vishwa Trading · INV-1052','12 min'],['Purchase order delivered','Vishwa Retail · Lanka Wholesale','28 min'],['Morning shift checked in','Colombo branch · 18 of 20 staff','42 min'],['Daily reconciliation completed','Vishwa Retail · Kandy branch','1 hour']].slice(0,4).map(([a,b,t])=>`<div class="event"><span class="event-dot"></span><div><h4>${a}</h4><p>${b}</p></div><time>${t}</time></div>`).join('')}</div></section>`}
function specialized(){let data={Customers:[['Pipeline value','LKR 2.8M','24 open opportunities across your businesses.'],['Customer relationships','1,248','Purchase history, balances and conversations in one view.'],['Needs a response','6','Two priority conversations waiting for your team.']],People:[['At work today','84 / 89','Attendance across seven branches and facilities.'],['Leave requests','2 pending','Review requests with tomorrow’s coverage in context.'],['Next payroll','Oct 25','Draft payroll · LKR 2,450,000 · Pending approval.']],Automations:[['Inventory replenishment','8 SKUs','Stock low → Draft purchase order → Owner approval.'],['Invoice collections','14 invoices','14 days overdue → Draft reminder → Owner approval.'],['Branch performance','7 locations','Sales below target → Notify manager → Escalate.']],Reports:[['Profit & loss','October 2026','Revenue, cost of goods and operating expenses by business.'],['Cash flow forecast','Next 30 days','Illustrative scenario range: LKR 5.1M–6.4M.'],['Sales performance','7 locations','Compare businesses, branches and product performance.']]};return `<div class="module-grid">${data[page].map(([t,n,d])=>`<section class="card"><h3>${t}</h3><span class="module-number">${n}</span><p>${d}</p><button data-module="${t}">Explore ${page==='Automations'?'workflow':'details'} →</button></section>`).join('')}</div><div class="grid">${businessTable()}${events()}</div>`}
function render(){let name=$('#business').value==='all'?'Your business':$('#business').selectedOptions[0].text;$('#title').textContent=page==='Overview'?name+', in focus.':{Approvals:'A few decisions. A big difference.',Finance:'Your finances, clearly.',Operations:'Keep every moving part in sync.',Customers:'Better relationships start here.',People:'Your people. Your greatest asset.',Automations:'Let the routine take care of itself.',Reports:'See the story behind the numbers.'}[page];$('#subtitle').textContent=page==='Overview'?'A clear view of today. A confident plan for what’s next.':{Approvals:'Review the context. Make the call. Move forward.',Finance:'Cash, commitments and confidence in one place.',Operations:'Stock, orders and branches — connected.',Customers:'A shared view of every customer and opportunity.',People:'A clearer view of attendance, coverage and payroll.',Automations:'Thoughtful workflows. Human control at every important step.',Reports:'Explore performance across businesses, branches and time.'}[page];$('#crumb').textContent=page;document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page==='Approvals')b.querySelector('.count').textContent=decisions.length});let brief=`<section class="brief"><span class="spark">✧</span><div><h3>A good morning to be in control. <span class="tag">AI BRIEFING</span></h3><p>Sales are <b>12.8% ahead</b> of the previous period. Retail is leading the way.<br>${decisions.length?'<b>'+decisions.length+' decisions</b> need your attention — start with the essentials reorder.':'All decisions reviewed. Your workspace is ready for the day.'}</p></div><button id="briefing">Read full briefing ↗</button></section>`;$('#content').innerHTML=(page==='Overview'?brief:'')+(page==='Approvals'?decisionCard(true):['Overview','Finance','Operations'].includes(page)?stats()+`<div class="grid">${chart()}${decisionCard()}</div><div class="grid">${businessTable()}${events()}</div>`:specialized())+`<form class="ask" id="ask"><span style="font-size:22px">✧</span><input aria-label="Ask about your business" placeholder="Ask Master Control anything about your business…"><kbd>AI PREVIEW</kbd><button>Ask ↗</button></form>`;bindContent()}
let focusBefore;function modal(html){focusBefore=document.activeElement;$('#dialog-body').innerHTML=html;$('#overlay').hidden=false;$('.close').focus()}function close(){ $('#overlay').hidden=true;focusBefore?.focus() }$('.close').onclick=close;$('#overlay').onclick=e=>{if(e.target===$('#overlay'))close()};document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&!$('#overlay').hidden){const a=[...$('.dialog').querySelectorAll('button,input,textarea,select,a')];let first=a[0],last=a[a.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();openSearch()}});function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function review(id){let d=decisions.find(d=>d.id===id);if(!d)return toast('All decisions reviewed.');modal(`<p class="eyebrow">${d.type.toUpperCase()} · PENDING APPROVAL</p><h2 id="dialog-title">${d.title}</h2><p>${d.why}</p><div class="detail-line"><span>Business</span><b>${d.desc.split(' · ')[0]}</b></div><div class="detail-line"><span>Reference</span><b>${d.detail}</b></div>${d.amount?`<div class="detail-line"><span>Amount</span><b>LKR ${money(d.amount)}</b></div>`:''}<p>Design preview: this updates the local decision queue only. No money, stock or messages are moved.</p><div class="dialog-actions"><button class="primary" id="approve">Approve draft</button><button id="edit">Edit draft</button><button id="reject">Reject</button></div>`);$('#approve').onclick=()=>resolve(d,'Approved');$('#reject').onclick=()=>resolve(d,'Rejected');$('#edit').onclick=()=>{modal(`<h2 id="dialog-title">Edit ${d.type.toLowerCase()}</h2><p>Adjust the proposed action before deciding.</p><textarea id="draft" aria-label="Draft content"></textarea><div class="dialog-actions"><button class="primary" id="save">Save draft</button></div>`);$('#draft').value=d.why;$('#save').onclick=()=>{if(!$('#draft').value.trim())return toast('Please enter draft details.');d.why=$('#draft').value.trim();review(d.id)}}}
function resolve(d,status){decisions=decisions.filter(x=>x.id!==d.id);activity.unshift([`${status}: ${d.type}`,d.desc,'Just now']);close();render();toast(`${status} in this design preview.`)}
function bindContent(){document.querySelectorAll('[data-decision]').forEach(el=>{el.onclick=()=>review(+el.dataset.decision);el.onkeydown=e=>{if(e.key==='Enter')el.click()}});if($('[data-review]'))$('[data-review]').onclick=()=>decisions.length?review(decisions[0].id):toast('You’re all caught up.');document.querySelectorAll('[data-business]').forEach(el=>{el.onclick=()=>{$('#business').value=el.dataset.business;render();toast('Showing '+$('#business').selectedOptions[0].text)};el.onkeydown=e=>{if(e.key==='Enter')el.click()}});document.querySelectorAll('[data-stat]').forEach(el=>el.onclick=()=>{if(el.dataset.stat==='Pending decisions'){page='Approvals';render();return}modal(`<p class="eyebrow">PERFORMANCE BREAKDOWN</p><h2 id="dialog-title">${el.dataset.stat}</h2><p>Illustrative figures for ${$('#period').selectedOptions[0].text.toLowerCase()}. Select a business below to drill down.</p>${scope().map(b=>`<div class="detail-line"><span>${b.name}</span><b>LKR ${money(el.dataset.stat.includes('Cash')?b.cash:Math.round(b.sales*factor()))}</b></div>`).join('')}<p>Production drill-down: Group → Business → Branch → Transaction.</p>`)});if($('#all-businesses'))$('#all-businesses').onclick=()=>{$('#business').value='all';render()};if($('#briefing'))$('#briefing').onclick=()=>modal(`<p class="eyebrow">DAILY BRIEFING · SAMPLE</p><h2 id="dialog-title">Your 10-minute business check-in.</h2><p><b>1. Start with stock.</b> Eight retail essentials need replenishment. Review the LKR 148,500 purchase order to protect tomorrow’s sales.</p><p><b>2. Collect what’s due.</b> Sunrise Distributors owes LKR 285,000. Review the drafted reminder.</p><p><b>3. Keep the floor covered.</b> Two leave requests affect tomorrow’s Colombo shift.</p><p><b>4. Watch manufacturing.</b> The facility is at 56% of its sales target. Compare orders and output with the branch manager.</p><p><b>5. Celebrate retail.</b> Retail leads the group with LKR 842,500 in sales.</p><p>This is scripted design content; Gemini and live business data are not connected.</p>`);$('#ask').onsubmit=e=>{e.preventDefault();let q=$('#ask input').value.trim();if(!q)return;modal(`<p class="eyebrow">MASTER CONTROL · AI DESIGN PREVIEW</p><h2 id="dialog-title">Business question</h2><p id="question"></p><p>In the finished system, this answer will be grounded in your ledger and operational records, with source transactions available to inspect.</p><div class="detail-line"><span>Sample retail sales</span><b>LKR 842,500</b></div><div class="detail-line"><span>Sample group cash</span><b>LKR 5,840,000</b></div><p>This prototype demonstrates the interaction; it does not query live records.</p>`);$('#question').textContent=q};document.querySelectorAll('[data-module]').forEach(el=>el.onclick=()=>modal(`<p class="eyebrow">${page.toUpperCase()} · DESIGN PREVIEW</p><h2 id="dialog-title">${el.dataset.module}</h2><p>${page==='Automations'?'Trigger → Evaluate condition → Prepare draft → Human approval → Record outcome.':'This focused workspace keeps business context visible while you inspect the underlying records.'}</p><div class="detail-line"><span>Scope</span><b>${$('#business').selectedOptions[0].text}</b></div><div class="detail-line"><span>Access</span><b>Owner workspace</b></div><p>Detailed forms and service connections belong to the phased production build.</p>`))}
document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{page=el.dataset.page;render()});$('#business').onchange=render;$('#period').onchange=render;$('#notifications').onclick=()=>{page='Approvals';render()};$('#guide').onclick=()=>modal(`<p class="eyebrow">DESIGN DIRECTION</p><h2 id="dialog-title">Clarity before complexity.</h2><p>A quiet canvas, forest-green actions and deliberate spacing keep the owner focused on decisions. Amber marks attention; red is reserved for urgent exceptions.</p><p><b>Owner overview:</b> briefing, four essential numbers, a ranked approval queue and business performance.</p><p><b>Focused workspaces:</b> finance, operations, customers, people, automations and reports.</p><p><b>Mobile:</b> the same priorities, stacked into a quick daily check-in with bottom navigation.</p><p>All records are illustrative. This is a design prototype of the product vision, not a completed phase of the production build guide.</p>`);
function openSearch(){modal('<h2 id="dialog-title">Find your workspace</h2><input id="search-input" placeholder="Search finance, stock, people…" aria-label="Search workspaces"><div id="results"></div>');const update=()=>{let q=$('#search-input').value.toLowerCase();$('#results').innerHTML=modules.filter(([n])=>n.toLowerCase().includes(q)||q==='stock'&&n==='Operations').map(([n,i])=>`<button data-result="${n}" style="display:block;width:100%;text-align:left;margin-top:8px">${i} &nbsp; ${n} →</button>`).join('');document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{page=b.dataset.result;close();render()})};$('#search-input').oninput=update;update();$('#search-input').focus()}$('#search').onclick=openSearch;render();


